INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein ISMS immer eine Risikoanalyse erfordert?', 2, '[{"text": "Nein", "correct": true, "because": "Standardmaßnahmen können ausreichen"}, {"text": "Ja", "correct": false, "because": "Nicht bei Basisabsicherung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Basisabsicherung?', 3, '[{"text": "Mindestschutz schnell umsetzen", "correct": true, "because": "Fokus auf grundlegende Maßnahmen"}, {"text": "Komplette Risikoeliminierung", "correct": false, "because": "Nicht realistisch"}, {"text": "Hohe Verfügbarkeit", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen gehören zur Standardabsicherung?', 5, '[{"text": "Firewall-Konfiguration", "correct": true, "because": "Schützt Netzwerkzugriff"}, {"text": "Patch-Management", "correct": true, "because": "Behebt Schwachstellen"}, {"text": "Schnelle Hardware", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Bunte Passwörter", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Bausteine decken typische Sicherheitsaspekte ab. b) Sie ersetzen ISO 27001.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bausteine ergänzen ISO 27001"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung eines Sicherheitskonzepts?', 4, '[{"text": "Bedrohungsanalyse", "correct": false, "because": "Identifiziert Risiken"}, {"text": "Zugriffskontrollen", "correct": false, "because": "Schützen Ressourcen"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Notfallplan immer zentral ist. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Wichtig für Reaktion auf Vorfälle"}, {"text": "Nein", "correct": false, "because": "Teil eines Gesamtkonzepts"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element gehört zu einem Sicherheitsmanagement?', 3, '[{"text": "Regelmäßige Audits", "correct": true, "because": "Prüfen Umsetzung"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Sicherheitsaspekt"}, {"text": "Großer Monitor", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte deckt ein Baustein für Netzwerksicherheit ab?', 5, '[{"text": "Segmentierung", "correct": true, "because": "Begrenzt Angriffsflächen"}, {"text": "Verschlüsselung", "correct": true, "because": "Schützt Datenfluss"}, {"text": "Schnelle Router", "correct": false, "because": "Nur Leistungsfaktor"}, {"text": "Bunte Kabel", "correct": false, "because": "Kein Sicherheitsvorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Basisabsicherung für KMUs reicht und b) Standardabsicherung immer komplexer ist. Stimmt das?', 3, '[{"text": "Beides stimmt", "correct": true, "because": "KMUs profitieren von Einfachheit, Standard ist umfassender"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Sicherheitskonzept?', 4, '[{"text": "Bedrohungskatalog", "correct": false, "because": "Hilft Risiken erkennen"}, {"text": "Maßnahmenplan", "correct": false, "because": "Definiert Umsetzung"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Baustein immer auf ein Thema beschränkt?', 2, '[{"text": "Ja", "correct": true, "because": "Fokussiert spezifische Aspekte"}, {"text": "Nein", "correct": false, "because": "Ein Thema pro Baustein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Baustein für Datensicherung?', 4, '[{"text": "Klare Anforderungen", "correct": true, "because": "Definiert Schutzmaßnahmen"}, {"text": "Wiederherstellungsplan", "correct": true, "because": "Sichert Datenverfügbarkeit"}, {"text": "Schnelle Installation", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Sicherheitsmaßnahmen immer teuer sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kosteneffiziente Lösungen möglich"}, {"text": "Ja", "correct": false, "because": "Kosten variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verfahren wähle ich für ein kleines Unternehmen?', 3, '[{"text": "Basisabsicherung", "correct": true, "because": "Einfach und schnell umsetzbar"}, {"text": "Kernabsicherung", "correct": false, "because": "Fokussiert Kritische Prozesse"}, {"text": "Vollständige Zertifizierung", "correct": false, "because": "Zu aufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Bausteine sind modular. b) Sie ersetzen Schulungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schulungen bleiben nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel hat ein Baustein für Clients?', 4, '[{"text": "Schutz vor Malware", "correct": true, "because": "Sichert Endgeräte"}, {"text": "Schnelle Updates", "correct": false, "because": "Teilmaßnahme"}, {"text": "Hohe Auflösung", "correct": false, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Baustein immer technische Maßnahmen enthält?', 2, '[{"text": "Nein", "correct": true, "because": "Auch organisatorische Maßnahmen"}, {"text": "Ja", "correct": false, "because": "Umfassender Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Kernabsicherung?', 4, '[{"text": "Schutz kritischer Prozesse", "correct": true, "because": "Fokussiert wesentliche Bereiche"}, {"text": "Vollständige Absicherung", "correct": false, "because": "Nur Teilbereiche"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Genauigkeit wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Bausteine nur für große Firmen geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Skalierbar für alle Größen"}, {"text": "Ja", "correct": false, "because": "Auch KMUs profitieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein Sicherheitskonzept effektiv?', 5, '[{"text": "Regelmäßige Überprüfung", "correct": true, "because": "Passt an neue Bedrohungen an"}, {"text": "Mitarbeiterschulung", "correct": true, "because": "Reduziert menschliche Fehler"}, {"text": "Teure Software", "correct": false, "because": "Nicht zwingend"}, {"text": "Großes Team", "correct": false, "because": "Effizienz wichtiger"}]');
